int cleanup_zip_archive(struct archive_read *a) {
  struct zip *zip = (struct zip *)a->format_data;
  int ret = ARCHIVE_OK;

  if (zip == NULL)
    return ARCHIVE_OK;

  // Free zlib decompression stream if valid
  if (zip->zlib_stream != NULL) {
    if (zip->zlib_stream->state != NULL)
      inflateEnd(zip->zlib_stream);
    free(zip->zlib_stream);
    zip->zlib_stream = NULL;
  }

  // Free LZMA decompression stream if valid
  if (zip->lzma_stream != NULL) {
    if (zip->lzma_stream->state != NULL)
      lzma_code_end(zip->lzma_stream);
    free(zip->lzma_stream);
    zip->lzma_stream = NULL;
  }

  // Free BZ2 decompression stream if valid
  if (zip->bz2_stream != NULL) {
    if (zip->bz2_stream->state != NULL)
      BZ2_bzDecompressEnd(zip->bz2_stream);
    free(zip->bz2_stream);
    zip->bz2_stream = NULL;
  }

  // Free ZIP entry resources
  struct zip_entry *entry = zip->entries;
  while (entry != NULL) {
    struct zip_entry *next = entry->next;

    if (entry->data != NULL)
      free(entry->data);

    if (entry->extra != NULL)
      free(entry->extra);

    free(entry);
    entry = next;
  }

  // Free main ZIP structure
  free(zip);
  a->format_data = NULL;

  return ret;
}
